#!/usr/bin/env python3
"""Filter and aggregate RFC-4180-style CSV files."""

from __future__ import annotations

import argparse
import csv
import json
import sys
from collections import OrderedDict
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Sequence, TextIO


class CsvInsightsError(Exception):
    """An error that should be reported to the command-line user."""


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Filter CSV rows and calculate grouped sums and averages."
    )
    parser.add_argument("input", metavar="INPUT.csv", help="input CSV file")
    parser.add_argument(
        "--where",
        action="append",
        default=[],
        metavar="COLUMN=VALUE",
        help="keep rows whose column exactly equals value (repeatable)",
    )
    parser.add_argument("--group-by", metavar="COLUMN", help="column used to group rows")
    parser.add_argument(
        "--sum", dest="sum_columns", action="append", default=[], metavar="COLUMN"
    )
    parser.add_argument(
        "--avg", dest="avg_columns", action="append", default=[], metavar="COLUMN"
    )
    parser.add_argument(
        "--output", choices=("json", "csv"), default="json", help="output format"
    )
    return parser


def validate_headers(headers: list[str]) -> None:
    if not headers:
        raise CsvInsightsError("input has no header row")
    empty_positions = [str(index + 1) for index, name in enumerate(headers) if name == ""]
    if empty_positions:
        raise CsvInsightsError(
            "header names must be non-empty (empty column position(s): "
            + ", ".join(empty_positions)
            + ")"
        )
    seen: set[str] = set()
    duplicates: list[str] = []
    for name in headers:
        if name in seen and name not in duplicates:
            duplicates.append(name)
        seen.add(name)
    if duplicates:
        raise CsvInsightsError("duplicate header name(s): " + ", ".join(duplicates))


def parse_filters(expressions: Sequence[str], headers: list[str]) -> list[tuple[int, str]]:
    positions = {name: index for index, name in enumerate(headers)}
    filters: list[tuple[int, str]] = []
    for expression in expressions:
        if "=" not in expression:
            raise CsvInsightsError(
                f"malformed filter {expression!r}: expected COLUMN=VALUE"
            )
        column, value = expression.split("=", 1)
        if not column:
            raise CsvInsightsError(
                f"malformed filter {expression!r}: column name is empty"
            )
        if column not in positions:
            raise CsvInsightsError(f"unknown column in --where: {column!r}")
        filters.append((positions[column], value))
    return filters


def column_positions(columns: Sequence[str], headers: list[str], option: str) -> list[int]:
    positions = {name: index for index, name in enumerate(headers)}
    result: list[int] = []
    for column in columns:
        if column not in positions:
            raise CsvInsightsError(f"unknown column for {option}: {column!r}")
        result.append(positions[column])
    return result


def decimal_string(value: Decimal) -> str:
    """Render a Decimal without exponent notation or insignificant zeroes."""
    if value == 0:
        return "0"
    rendered = format(value, "f")
    if "." in rendered:
        rendered = rendered.rstrip("0").rstrip(".")
    return rendered


def read_csv(path: Path) -> tuple[list[str], list[list[str]]]:
    try:
        source = path.open("r", encoding="utf-8", newline="")
    except (OSError, UnicodeError) as exc:
        raise CsvInsightsError(f"cannot open input file {str(path)!r}: {exc}") from exc

    try:
        with source:
            reader = csv.reader(source, strict=True)
            try:
                headers = next(reader)
            except StopIteration:
                raise CsvInsightsError("input is empty") from None
            validate_headers(headers)
            rows: list[list[str]] = []
            for record_number, row in enumerate(reader, start=2):
                if len(row) != len(headers):
                    raise CsvInsightsError(
                        f"row {record_number} has {len(row)} field(s); "
                        f"expected {len(headers)}"
                    )
                rows.append(row)
            return headers, rows
    except csv.Error as exc:
        line = reader.line_num if "reader" in locals() else "unknown"
        raise CsvInsightsError(f"malformed CSV near line {line}: {exc}") from exc
    except UnicodeError as exc:
        raise CsvInsightsError(f"input is not valid UTF-8: {exc}") from exc


def filtered_rows(
    rows: Sequence[list[str]], filters: Sequence[tuple[int, str]]
) -> list[tuple[int, list[str]]]:
    return [
        (row_number, row)
        for row_number, row in enumerate(rows, start=2)
        if all(row[index] == expected for index, expected in filters)
    ]


def aggregate(
    rows: Sequence[tuple[int, list[str]]],
    headers: list[str],
    group_index: int,
    sum_columns: Sequence[str],
    sum_indices: Sequence[int],
    avg_columns: Sequence[str],
    avg_indices: Sequence[int],
) -> tuple[list[str], list[list[str]]]:
    numeric_columns: list[tuple[str, int]] = list(zip(sum_columns, sum_indices))
    numeric_columns.extend(zip(avg_columns, avg_indices))
    groups: OrderedDict[str, list[list[Decimal]]] = OrderedDict()

    for row_number, row in rows:
        values: list[Decimal] = []
        for column, index in numeric_columns:
            cell = row[index]
            if cell == "":
                raise CsvInsightsError(
                    f"row {row_number}, column {column!r}: numeric value is blank"
                )
            try:
                number = Decimal(cell)
            except InvalidOperation as exc:
                raise CsvInsightsError(
                    f"row {row_number}, column {column!r}: invalid numeric value {cell!r}"
                ) from exc
            if not number.is_finite():
                raise CsvInsightsError(
                    f"row {row_number}, column {column!r}: invalid numeric value {cell!r}"
                )
            values.append(number)

        group = row[group_index]
        if group not in groups:
            groups[group] = [[Decimal(0), Decimal(0)] for _ in numeric_columns]
        accumulators = groups[group]
        for index, value in enumerate(values):
            accumulators[index][0] += value
            accumulators[index][1] += 1

    output_headers = [headers[group_index]]
    output_headers.extend(f"sum_{column}" for column in sum_columns)
    output_headers.extend(f"avg_{column}" for column in avg_columns)
    output_rows: list[list[str]] = []
    sum_count = len(sum_columns)
    for group in sorted(groups):
        accumulators = groups[group]
        output = [group]
        output.extend(decimal_string(total) for total, _ in accumulators[:sum_count])
        output.extend(
            decimal_string(total / count)
            for total, count in accumulators[sum_count:]
        )
        output_rows.append(output)
    return output_headers, output_rows


def emit_json(headers: Sequence[str], rows: Sequence[Sequence[str]], output: TextIO) -> None:
    records = [dict(zip(headers, row)) for row in rows]
    json.dump(records, output, ensure_ascii=False, separators=(",", ":"))
    output.write("\n")


def emit_csv(headers: Sequence[str], rows: Sequence[Sequence[str]], output: TextIO) -> None:
    writer = csv.writer(output, lineterminator="\r\n")
    writer.writerow(headers)
    writer.writerows(rows)


def run(args: argparse.Namespace) -> None:
    if (args.sum_columns or args.avg_columns) and not args.group_by:
        raise CsvInsightsError("--sum and --avg require --group-by")
    if args.group_by and not (args.sum_columns or args.avg_columns):
        raise CsvInsightsError("--group-by requires --sum or --avg")

    headers, rows = read_csv(Path(args.input))
    filters = parse_filters(args.where, headers)
    selected = filtered_rows(rows, filters)

    if args.group_by:
        group_index = column_positions([args.group_by], headers, "--group-by")[0]
        sum_indices = column_positions(args.sum_columns, headers, "--sum")
        avg_indices = column_positions(args.avg_columns, headers, "--avg")
        output_headers, output_rows = aggregate(
            selected,
            headers,
            group_index,
            args.sum_columns,
            sum_indices,
            args.avg_columns,
            avg_indices,
        )
    else:
        output_headers = headers
        output_rows = [row for _, row in selected]

    if args.output == "json":
        emit_json(output_headers, output_rows, sys.stdout)
    else:
        emit_csv(output_headers, output_rows, sys.stdout)


def main(argv: Sequence[str] | None = None) -> int:
    parser = build_parser()
    try:
        args = parser.parse_args(argv)
        run(args)
    except CsvInsightsError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    except BrokenPipeError:
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
# CSV Insights

A dependency-free Python 3.11+ command-line tool for filtering CSV data and
calculating grouped sums and averages with exact decimal arithmetic.

```console
python3 main.py INPUT.csv [--where COLUMN=VALUE ...] [--group-by COLUMN] \
  [--sum COLUMN] [--avg COLUMN] [--output json|csv]
```

Output defaults to JSON. Filters are exact string comparisons and repeated
filters are combined with AND. `--sum` and `--avg` may each be repeated, and
require `--group-by`.

Examples:

```console
python3 main.py sales.csv --where region=West
python3 main.py sales.csv --group-by region --sum revenue --avg units --output csv
```

The input must be UTF-8 CSV with a non-empty, unique header. Invalid row widths
and invalid or blank numeric cells produce a descriptive error and a non-zero
exit status. The input file is only read and is never modified.
